const SUITE_NOTES = {
  sources: {
    title: "One corpus, read once",
    body: "Service code, infrastructure- and config-as-code, architecture docs, runbooks and telemetry \u2014 the same set feeds everything downstream.",
    detail: "Config-as-code is the half that carries the weight: it declares what the live environment is SUPPOSED to be. During an incident that intent is precisely what nobody can locate, and it is the difference between an assistant that recites a wiki and one that can reason about the system actually running."
  },
  builder: {
    title: "Expert system builder",
    body: "Compiles a corpus into an expert system \u2014 extracting what is there, linking every extracted claim back to the line it came from.",
    detail: "The builder is the reusable half. Pointing it at a new service or domain produces a new expert system without anyone hand-curating a knowledge base, which is what makes coverage across a large estate affordable at all. A hand-built knowledge base covers the service someone had time for."
  },
  systems: {
    title: "Expert systems \u2014 one per service or domain",
    body: "Each is a queryable artifact scoped to a service or a domain, carrying that scope's code, declared configuration, documentation and known findings.",
    detail: "Scoping matters. One giant index answers vaguely about everything; a per-domain system answers precisely about its own, and a question that genuinely spans domains is answered by querying several and reconciling \u2014 which is a different and better operation than blending everything into one soup up front."
  },
  backend: {
    title: "Expert system backend",
    body: "Hosts the systems and serves queries \u2014 against one system, or fanned across a cluster of them when a question crosses boundaries.",
    detail: "Cluster query is the capability incidents actually need. A real incident rarely respects a service boundary: the symptom is in one domain, the cause in its dependency. Fanning a single question across the relevant systems and reconciling the answers, with each fragment still carrying its provenance, is how you get an answer that spans the blast radius without losing the ability to check it."
  },
  readiness: {
    title: "Readiness inventory",
    body: "Scans the same corpus for failure modes that come from configuration rather than from code \u2014 thundering herd, retry storms, missing backpressure, single points of failure.",
    detail: "These are the incidents that are visible in the declared configuration before they ever fire, and they are invisible in a code review because no single file looks wrong. The findings are written back into the expert systems, so the assistant answering a duty officer at 3am already knows this service has an unbounded retry with no jitter \u2014 it is not being asked to notice that under time pressure."
  },
  chat: {
    title: "Duty officer chat",
    body: "Ask the expert system during a live incident instead of hunting through wikis, dashboards and dependency diagrams while the clock runs.",
    detail: "Grounded in the declared configuration and the known findings, so it answers about this system rather than about systems in general."
  },
  incident: {
    title: "Incident command dashboard",
    body: "Real-time organisation of the response \u2014 investigation lanes and their owners, action items, who has been paged and who has actually joined, and current impact.",
    detail: "The part of an incident that most often fails is not the technical diagnosis, it is coordination: two people investigating the same lane, a critical owner paged but never joined, an action item everyone assumed someone else had. This makes that state visible instead of implicit in a chat thread."
  },
  teams: {
    title: "Back to the application teams",
    body: "The findings catalogue is also a fix list \u2014 the failure modes go back to the teams that own the configuration.",
    detail: "A prevention loop as much as a response one. The cheapest incident is the one that never fires."
  },
  foundations: {
    title: "Agentic foundations \u2014 the bedrock",
    body: "Every finding and every answer is sourced to evidence. The agentic and data engineering underneath is what makes that a property of the system rather than an aspiration.",
    detail: "This is the part that makes the rest usable in a regulated environment. An assistant that cannot show its work is an assistant nobody is allowed to act on during a Sev1, and a findings catalogue nobody can audit is a catalogue nobody will act on. Determinism where determinism is possible, provenance on everything else."
  }
};
